import pandas as pd, numpy as np
for e in ['experiment_1_csv','experiment_2_csv','experiment_6_csv','experiment_7_csv','experiment_8_csv']:
    try:
        df=pd.read_csv(eval(e))
        if 'do_LineFlushRate' in df.columns:
            print(e, df['do_LineFlushRate'].describe()[['min','mean','max']].round(2).to_dict())
            # group by flush bins
            df['fb']=pd.cut(df['do_LineFlushRate'],5)
            print(df.groupby('fb',observed=True)['WaterClarityScore'].mean().round(2))
    except Exception as ex:
        print(e,ex)
